<script setup lang="ts">
/**
 * <EmploiLogo /> — Emploi brand logo (ID badge concept), inline SVG.
 * Follows the app's `.dark` class automatically via CSS variables.
 *
 *   <EmploiLogo />                      horizontal lockup
 *   <EmploiLogo variant="mark" :size="32" />
 *   <EmploiLogo variant="stacked" :size="120" tagline />
 *
 * `size` = rendered height in px.
 * Override colours anywhere with --emploi-logo-badge, --emploi-logo-slot,
 * --emploi-logo-person, --emploi-logo-text and --emploi-logo-sub.
 */
const props = withDefaults(defineProps<{
  variant?: 'horizontal' | 'stacked' | 'mark'
  size?: number | string
  tagline?: boolean
}>(), {
  variant: 'horizontal',
  size: 36,
  tagline: false
})

const numericSize = computed(() => Number(props.size) || 36)

const viewBox = computed(() => {
  if (props.variant === 'mark') return '0 0 64 64'
  if (props.variant === 'stacked') return `0 0 300 ${props.tagline ? 190 : 165}`
  return '0 0 203.9 64'
})

const ratio = computed(() => {
  const [, , w, h] = viewBox.value.split(' ').map(Number)
  return (w && h) ? w / h : 1
})

const computedWidth = computed(() => Math.round(numericSize.value * ratio.value * 10) / 10)
</script>

